-- 631 PAPIC CHALLENGES, AND A BOARD THAT KNOWS WHAT KIND OF PARTY IT IS.
--
-- Owner, 2026-08-21: "we want to create a 500 papic challenges … activities
-- that they can talk make people do during the event. or something they can
-- share to the host. like a greeting, a story." Plus the seven shapes he named
-- — a confession box · an on-the-spot anywhere challenge · one that includes
-- the host · one that includes other people · a selfie · a flex of what they
-- wore or brought · a special message for the couple.
--
-- The rows themselves are GENERATED from apps/web/lib/papic-challenge-pool.ts —
-- see the block at the bottom, and `scripts/emit-papic-challenge-pool.mjs`.
-- Six hundred rows cannot be kept in step with a hand-typed migration.
--
-- ── 🚨 A LIVE DEFECT IS FIXED HERE, MEASURED NOT ASSUMED ───────────────────
-- Every one of the 60 shipped challenges was written for a wedding, and the
-- library had no way to SAY so. Read out of production on 2026-08-21: the event
-- `movie-night` is of type `date` and carries a full 20-slot board asking two
-- people to "dance with the bride or groom", to "catch the newlyweds mid-kiss"
-- and to get "a photo with one of the couple's parents".
-- `event_types` gives a row a scope, and both lanes of `ensure_papic_board`
-- now ask for it. Nothing is deleted: a wedding row on a date's board simply
-- loses its slot the next time the board is built, and 475 of the 631 rows fit
-- any celebration, so no board goes short.
-- ✅ Safe by arithmetic, not optimism: production holds ZERO mission
-- completions, so no guest is un-finished by a row leaving a board.

BEGIN;

-- ── 1 · ROOM FOR THE POOL ──────────────────────────────────────────────────
-- 1..99 was sized for a library of 40. `library_id` is a smallint (max 32767),
-- so the column already fits; only its CHECK was in the way.
-- 🪤 A `DROP CONSTRAINT IF EXISTS` ON A WRONG NAME IS A SILENT NO-OP — the old
-- bound survives and the insert then fails with nothing pointing at the cause.
-- This name was read out of `pg_constraint` in production, not guessed, and the
-- db test asserts the new bound by USING it.
ALTER TABLE public.papic_challenge_library
  DROP CONSTRAINT IF EXISTS papic_challenge_library_library_id_check;
ALTER TABLE public.papic_challenge_library
  ADD CONSTRAINT papic_challenge_library_library_id_check
  CHECK (library_id >= 1 AND library_id <= 9999);

-- ── 2 · WHAT KIND OF EVENT IS THIS ROW FOR ─────────────────────────────────
-- NULL = fits any celebration. A list = only those types.
-- ⚠ NULL IS THE PERMISSIVE VALUE ON PURPOSE. A row added later without thinking
-- about scope shows up everywhere, which is how the existing sixty behaved and
-- is therefore not a regression; the alternative — defaulting to wedding-only —
-- would silently hide new work from every other event type.
ALTER TABLE public.papic_challenge_library
  ADD COLUMN IF NOT EXISTS event_types text[];

COMMENT ON COLUMN public.papic_challenge_library.event_types IS
  'Which event types this challenge fits. NULL = any. A list = only those. '
  'Added 2026-08-21 because all 60 original rows were wedding-worded and a '
  '`date` event in production was carrying a board that asked about newlyweds.';

-- ── 3 · TOKENS THE PROMPTS MAY CARRY ───────────────────────────────────────
-- Documented on the table a reader actually queries, because the prompts are
-- data and a comment in TypeScript never reaches somebody reading the rows.
COMMENT ON COLUMN public.papic_challenge_library.prompt IS
  'What the guest reads. May carry tokens resolved at READ time, never stored '
  'resolved: {who} (wedding only — the bride/the groom/the couple, per guest, '
  'from guests.side) · {host} (the couple/the celebrant/the graduate/the host) '
  '· {hosts} (the same, possessive) · {event} (wedding/birthday/…). {host} is '
  'only ever an OBJECT — "the couple" takes a plural verb and "the celebrant" a '
  'singular one, so no prompt may let it start a clause.';

COMMIT;

-- ── 4 · THE POOL ───────────────────────────────────────────────────────────
BEGIN;

-- GENERATED by scripts/emit-papic-challenge-pool.mjs — DO NOT EDIT BY HAND.
-- Source of truth: apps/web/lib/papic-challenge-pool.ts (631 challenges).
ON CONFLICT (library_id) DO UPDATE SET
  slug          = EXCLUDED.slug,
  category      = EXCLUDED.category,
  title         = EXCLUDED.title,
  prompt        = EXCLUDED.prompt,
  capture_kind  = EXCLUDED.capture_kind,
  mission_type  = EXCLUDED.mission_type,
  priority_rank = EXCLUDED.priority_rank,
  event_types   = EXCLUDED.event_types;

COMMIT;

-- ── 5 · THE BOARD ASKS WHAT KIND OF PARTY THIS IS ──────────────────────────
-- Byte-identical to the live function except for the event-type scope, which is
-- added in BOTH lanes. One lane alone is not a fix: the INSERT picks WHICH rows
-- get materialized and the slotting CTE picks which materialized rows get a
-- SLOT, so scoping only the INSERT would leave the wedding rows already sitting
-- on `movie-night`'s board exactly where they are.
--
-- 🔑 AN UNKNOWN EVENT RESOLVES TO NO TYPE, AND THAT FAILS CLOSED. If the event
-- row is missing, `v_event_type` is NULL, `NULL = ANY(l.event_types)` is NULL,
-- and only the unscoped rows survive — plain wording, never a wedding word at
-- something that is not one.
CREATE OR REPLACE FUNCTION public.ensure_papic_board(p_event_id uuid, p_pabati_active boolean DEFAULT false)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_couple_used INTEGER;
  v_vendor_used INTEGER;
  v_target      INTEGER;
  v_slotted     INTEGER;
  v_event_type  TEXT;
BEGIN
  -- Auth: the event's couple or coordinator, an admin, or service_role (server).
  -- NOT anon.
  --
  -- ⚠ The single-line form of this comment failed the secret scan. gitleaks'
  -- generic-api-key rule read the slash-joined role list as one high-entropy
  -- token and reported a leak at this line — in a COMMENT, with no credential
  -- anywhere near it. Split rather than suppressed: an inline `gitleaks:allow`
  -- would silence the rule here permanently, and a suppression marker on a line
  -- that never held a secret is a marker nobody can later evaluate.
  IF auth.uid() IS NOT NULL
     AND NOT public.is_admin()
     AND NOT EXISTS (
       SELECT 1 FROM public.event_members em
       WHERE em.event_id = p_event_id AND em.user_id = auth.uid()
         AND em.member_type IN ('couple','coordinator')
     ) THEN
    RAISE EXCEPTION 'not authorized to build the Papic board for event %', p_event_id;
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('papic_board:' || p_event_id::text));

  -- ⬇ THE ONE-LINE FIX. Was ensure_papic_auto_missions(...), whose 2026-08-01
  -- NULL-session refusal aborted this whole function on the guest path — the
  -- only path that ever calls it — leaving every event with no board at all.
  -- We have authorized above; call the step, not the public door.
  PERFORM public.papic_generate_booth_missions_unchecked(p_event_id);

  -- What kind of celebration is this? Read once; both lanes use it.
  SELECT e.event_type INTO v_event_type
  FROM public.events e WHERE e.event_id = p_event_id;

  -- Lane sizes. Caps: couple 10, vendor 5. Setnayan backfills the remainder to 20.
  SELECT LEAST(COUNT(*), 10) INTO v_couple_used
  FROM public.papic_missions m
  WHERE m.event_id = p_event_id AND m.source = 'couple' AND m.is_active AND m.approved;

  SELECT LEAST(COUNT(*), 5) INTO v_vendor_used
  FROM public.papic_missions m
  WHERE m.event_id = p_event_id AND m.source IN ('vendor','auto') AND m.is_active AND m.approved
    AND m.vendor_id IN (
      SELECT ev.vendor_id FROM public.event_vendors ev
      WHERE ev.event_id = p_event_id
        AND ev.status IN ('contracted','deposit_paid','delivered','complete')
    );

  v_target := 20 - v_couple_used - v_vendor_used;  -- structurally >= 5 -> Top-5 always fits.

  -- Materialize the Setnayan fills: top-ranked library items NOT taken by a couple pick, NOT vetoed
  -- (an inactive setnayan tombstone), Pabati only if the SKU is active, and only rows whose scope
  -- admits this event type. Idempotent via the partial unique. Existing active setnayan rows
  -- conflict -> DO NOTHING (kept, never re-created).
  IF v_target > 0 THEN
    SELECT src.event_id, src.mission_type, 'setnayan', src.prompt, src.library_id, src.capture_kind, true, true
    FROM (
      SELECT p_event_id AS event_id, l.mission_type, l.prompt, l.library_id, l.capture_kind
      FROM public.papic_challenge_library l
      WHERE l.is_active
        AND l.mission_type <> 'face_verified'
        AND (l.capture_kind <> 'pabati' OR p_pabati_active)
        AND (l.event_types IS NULL OR v_event_type = ANY (l.event_types))
        AND NOT EXISTS (  -- taken by a couple pick
          SELECT 1 FROM public.papic_missions cm
          WHERE cm.event_id = p_event_id AND cm.source = 'couple'
            AND cm.is_active AND cm.approved AND cm.library_id = l.library_id)
        AND NOT EXISTS (  -- vetoed tombstone (couple hid this hero)
          SELECT 1 FROM public.papic_missions vm
          WHERE vm.event_id = p_event_id AND vm.source = 'setnayan'
            AND vm.library_id = l.library_id AND NOT vm.is_active)
      ORDER BY l.priority_rank NULLS LAST, l.library_id
      LIMIT v_target
    ) src
    ON CONFLICT (event_id, library_id) WHERE source = 'setnayan' DO NOTHING;
  END IF;

  -- Reset the board, then reassign board_slot deterministically across the three lanes.
  UPDATE public.papic_missions
    SET board_slot = NULL, updated_at = NOW()
  WHERE event_id = p_event_id AND board_slot IS NOT NULL;

  WITH cand AS (
    -- couple lane (slots first): active/approved couple rows by created_at, id.
    SELECT m.mission_id, 0 AS lane,
           row_number() OVER (ORDER BY m.created_at, m.id) AS lane_rank
    FROM public.papic_missions m
    WHERE m.event_id = p_event_id AND m.source = 'couple' AND m.is_active AND m.approved
    UNION ALL
    -- vendor lane: PAID (source='vendor', approved) before FREE booth (source='auto'); booked vendors only.
    SELECT m.mission_id, 1 AS lane,
           row_number() OVER (
             ORDER BY CASE WHEN m.source = 'vendor' THEN 0 ELSE 1 END, m.created_at, m.id
           ) AS lane_rank
    FROM public.papic_missions m
    WHERE m.event_id = p_event_id AND m.source IN ('vendor','auto') AND m.is_active AND m.approved
      AND m.vendor_id IN (
        SELECT ev.vendor_id FROM public.event_vendors ev
        WHERE ev.event_id = p_event_id
          AND ev.status IN ('contracted','deposit_paid','delivered','complete'))
    UNION ALL
    -- setnayan lane: by priority_rank then library order; exclude Pabati-if-inactive, couple-taken,
    -- and anything whose scope does not admit this event type.
    SELECT m.mission_id, 2 AS lane,
           row_number() OVER (ORDER BY l.priority_rank NULLS LAST, l.library_id) AS lane_rank
    FROM public.papic_missions m
    JOIN public.papic_challenge_library l ON l.library_id = m.library_id
    WHERE m.event_id = p_event_id AND m.source = 'setnayan' AND m.is_active AND m.approved
      AND l.is_active
      AND (l.capture_kind <> 'pabati' OR p_pabati_active)
      AND (l.event_types IS NULL OR v_event_type = ANY (l.event_types))
      AND NOT EXISTS (  -- dedup: a couple pick of the same library item wins the slot
        SELECT 1 FROM public.papic_missions cm
        WHERE cm.event_id = p_event_id AND cm.source = 'couple'
          AND cm.is_active AND cm.approved AND cm.library_id = m.library_id)
  ),
  capped AS (
    SELECT mission_id, lane, lane_rank FROM cand
    WHERE (lane = 0 AND lane_rank <= v_couple_used)
       OR (lane = 1 AND lane_rank <= v_vendor_used)
       OR (lane = 2 AND lane_rank <= v_target)
  ),
  slotted AS (
    SELECT mission_id, row_number() OVER (ORDER BY lane, lane_rank) AS slot
    FROM capped
  )
  UPDATE public.papic_missions m
    SET board_slot = s.slot, updated_at = NOW()
  FROM slotted s
  WHERE m.mission_id = s.mission_id;

  GET DIAGNOSTICS v_slotted = ROW_COUNT;
  RETURN v_slotted;
END;
$function$;

-- ── 6 · THE GUEST READER LEARNS THREE MORE WORDS (v5 -> v6) ────────────────
-- v5 resolved {who} per guest. v6 adds {host}, {hosts} and {event}, resolved
-- per EVENT from `event_type_profiles.terminology` — the same block the guest
-- tree's own vocabulary reads, so a birthday's Papic board and a birthday's
-- seating page finally use the same word for the same person.
--
-- 🔑 SUBSTITUTION STAYS IN THE PER-GUEST READER, WHERE {who} ALREADY LIVES.
-- The board is materialized per EVENT — one row serves every guest — so baking
-- a word in at materialization would freeze it, and a prompt is copied into
-- `papic_missions` at that moment. Resolving here means an event that changes
-- type, or a terminology fix, reaches boards that already exist.
--
-- 🔒 A PROMPT WITH NO TOKEN COMES BACK BYTE-IDENTICAL. `replace()` on a string
-- that does not contain the needle returns the string. Every couple-authored
-- and vendor-authored prompt is therefore untouched, and so are the 60 shipped
-- challenges that carry no token.
--
-- ⚠ THE SIGNATURE IS UNCHANGED, WHICH IS THE ONLY REASON `CREATE OR REPLACE` IS
-- SAFE HERE — this function has a fixed RETURNS TABLE, and widening it would
-- need DROP + CREATE + re-GRANT.
CREATE OR REPLACE FUNCTION public.papic_guest_missions(p_guest_id uuid)
 RETURNS TABLE(mission_id uuid, mission_type text, prompt text, vendor_id uuid, vendor_name text, target_guest_id uuid, target_role guest_role, completed boolean, consent_shared boolean, source text, capture_kind text, library_id smallint, board_slot smallint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_event_id   UUID;
  v_guest_role public.guest_role;
  v_guest_side public.guest_side;
  v_who        TEXT;
  v_host_noun  TEXT;
  v_host       TEXT;
  v_hosts      TEXT;
  v_event_word TEXT;
  v_has_board  BOOLEAN;
BEGIN
  SELECT g.event_id, g.role, g.side
    INTO v_event_id, v_guest_role, v_guest_side
  FROM public.guests g
  WHERE g.guest_id = p_guest_id AND g.deleted_at IS NULL;
  IF v_event_id IS NULL THEN
    RETURN;  -- unknown / deleted guest -> empty set
  END IF;

  -- The side word. ELSE covers 'both' AND any enum value added later: an
  -- unknown side falls back to "the couple", which is the one phrasing that is
  -- never wrong for anybody. Fail toward the neutral truth, never toward a
  -- guess about whose guest this is.
  v_who := CASE v_guest_side
             WHEN 'bride' THEN 'the bride'
             WHEN 'groom' THEN 'the groom'
             ELSE 'the couple'
           END;

  -- Who is throwing this one, and what it is called. A LEFT JOIN and two
  -- COALESCEs: a missing profile row, a missing key, or a blank string all land
  -- on "the host" / "event", which is plain but correct at every event type.
  -- An empty organiser noun would otherwise render "A photo with the .".
  SELECT NULLIF(btrim(p.terminology->>'organizer_noun'), ''),
         NULLIF(btrim(p.terminology->>'event_word'), '')
    INTO v_host_noun, v_event_word
  FROM public.events e
  LEFT JOIN public.event_type_profiles p ON p.event_type = e.event_type
  WHERE e.event_id = v_event_id;

  v_host_noun  := COALESCE(v_host_noun, 'host');
  v_event_word := COALESCE(v_event_word, 'event');
  v_host       := 'the ' || v_host_noun;
  -- A noun already ending in s takes the bare mark ("parents’", not "parents’s").
  -- No seeded value ends in s today; one added later would otherwise read wrong
  -- on every prompt at once, which is why this is a branch and not a concat.
  v_hosts      := v_host || CASE WHEN right(v_host_noun, 1) = 's' THEN '’' ELSE '’s' END;

  -- Has a board been materialized for this event? If not, FAIL-SOFT to v3
  -- behaviour (show all active/approved missions by created_at) — the flag is
  -- LIVE in prod, so this reader must not blank today's missions.
  SELECT EXISTS (
    SELECT 1 FROM public.papic_missions m
    WHERE m.event_id = v_event_id AND m.board_slot IS NOT NULL
  ) INTO v_has_board;

  RETURN QUERY
  SELECT m.mission_id, m.mission_type,
         -- {hosts} is replaced BEFORE {host}. The other order turns "{hosts}"
         -- into "the couple}s" — the shorter needle matches inside the longer
         -- token and eats its opening brace.
         replace(
           replace(
             replace(
               replace(m.prompt, '{who}', v_who),
             '{hosts}', v_hosts),
           '{host}', v_host),
         '{event}', v_event_word) AS prompt,
         m.vendor_id, ev.vendor_name,
         m.target_guest_id, m.target_role,
         (c.completion_id IS NOT NULL) AS completed,
         COALESCE(c.consent_to_share, false) AS consent_shared,
         m.source, m.capture_kind, m.library_id, m.board_slot
  FROM public.papic_missions m
  LEFT JOIN public.event_vendors ev ON ev.vendor_id = m.vendor_id
  LEFT JOIN public.papic_mission_completions c
    ON c.mission_id = m.mission_id AND c.guest_id = p_guest_id
  WHERE m.event_id = v_event_id
    AND m.is_active
    AND m.approved
    -- targeted (roster) missions show only to the targeted guest; general missions show to all.
    AND (m.target_guest_id IS NULL OR m.target_guest_id = p_guest_id)
    -- role-scoped missions show only to a guest of that role (fail-CLOSED — v3 guard carried forward).
    AND (m.target_role IS NULL OR m.target_role = v_guest_role)
    AND (
      NOT v_has_board                 -- fail-soft: no board -> show all (v3 behaviour)
      OR m.board_slot IS NOT NULL     -- on the board (the live <=20)
      OR c.completion_id IS NOT NULL  -- completed-off-board -> the "Done" archive (never un-finish a guest)
    )
  ORDER BY (c.completion_id IS NOT NULL), m.board_slot NULLS LAST, m.created_at;
END;
$function$;

COMMENT ON FUNCTION public.papic_guest_missions(uuid) IS
  'v6 (2026-08-21). The guest''s live challenge board. Resolves four tokens at '
  'READ time and never stores them resolved: {who} per guest from guests.side '
  '(wedding only), and {host} / {hosts} / {event} per event from '
  'event_type_profiles.terminology. A prompt with no token is returned '
  'byte-identical. {hosts} is replaced before {host} — the other order eats the '
  'longer token''s brace.';

-- ── 7 · WHAT OTHER COUPLES ACTUALLY PICKED ─────────────────────────────────
-- Owner, 2026-08-21: "we will show the top 20 most picked challenges."
--
-- A couple can only READ THEIR OWN event's missions — RLS says so, correctly —
-- so popularity across every event is not something the picker can compute for
-- itself. This is the narrowest possible door: a count per library row and
-- nothing else. No event ids, no names, no dates, nothing that says WHO picked
-- anything. `count(DISTINCT event_id)` so one event that adds and removes a
-- challenge repeatedly cannot vote twice.
--
-- ⚠ IT WILL RETURN AN EMPTY SET FOR A WHILE, AND THAT IS THE INTERESTING CASE.
-- Production holds ZERO couple picks today. A "Most picked" shelf built on this
-- alone would be BLANK on the day it ships — the empty-rail failure this project
-- has now met four times. The picker therefore falls back to the curated order
-- AND CHANGES ITS OWN SUBHEADING to say which of the two it is showing; see
-- `couple-challenges-manager.tsx`. Never present the fallback as popularity.
CREATE OR REPLACE FUNCTION public.papic_challenge_pick_counts()
 RETURNS TABLE(library_id smallint, picks integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT m.library_id, count(DISTINCT m.event_id)::int AS picks
  FROM public.papic_missions m
  WHERE m.source = 'couple'
    AND m.library_id IS NOT NULL
    AND m.is_active
  GROUP BY m.library_id;
$function$;

COMMENT ON FUNCTION public.papic_challenge_pick_counts() IS
  'How many DIFFERENT events have each library challenge on them, as a couple''s '
  'own pick. Aggregate only — no event, guest or vendor identity crosses this '
  'boundary, which is why it may be SECURITY DEFINER while papic_missions stays '
  'RLS-scoped. Feeds the picker''s "Most picked" shelf. Returns an empty set '
  'until couples start picking; the caller must NOT present its fallback '
  'ordering as popularity.';

REVOKE ALL ON FUNCTION public.papic_challenge_pick_counts() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.papic_challenge_pick_counts() TO authenticated;
